import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    TrendingUp, Award, Target, CalendarCheck, 
    Flame, Clock, CheckCircle, Circle, ArrowRight,
    Sparkles, Zap, Users, BookOpen, Code2, Database
} from 'lucide-react';
import axios from 'axios';
import { motion } from 'framer-motion';

const Dashboard = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const [tasks, setTasks] = useState([]);

    const targetDate = new Date(2026, 10, 30);
    const today = new Date();
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));

    useEffect(() => {
        if (user) {
            fetchData();
        }
    }, [user]);

    const fetchData = async () => {
        try {
            const tasksRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasksRes.data);

            const statsRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(statsRes.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch data:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500"></div>
            </div>
        );
    }

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted === true).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const calculateStreak = () => {
        let streak = 0;
        const sortedTasks = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sortedTasks) {
            if (task.overallCompleted === true) {
                streak++;
            } else {
                break;
            }
        }
        return streak;
    };

    const streak = calculateStreak();

    const todayDay = new Date().getDate();
    const todayTasks = tasks.filter(t => t.day === todayDay);
    const todayCompleted = todayTasks.filter(t => t.overallCompleted === true).length;

    const weekTasks = tasks.filter(t => t.day >= 25 && t.day <= 31);
    const weekCompleted = weekTasks.filter(t => t.overallCompleted === true).length;
    const weekProgress = weekTasks.length > 0 ? Math.round((weekCompleted / weekTasks.length) * 100) : 0;

    const quickStats = [
        { label: 'Total Tasks', value: totalTasks, icon: CheckCircle, color: 'text-indigo-500', bg: 'bg-indigo-50' },
        { label: 'Completed', value: completedTasks, icon: Award, color: 'text-green-500', bg: 'bg-green-50' },
        { label: 'Streak', value: `${streak} days`, icon: Flame, color: 'text-orange-500', bg: 'bg-orange-50' },
        { label: 'Left', value: `${daysRemaining} days`, icon: Target, color: 'text-purple-500', bg: 'bg-purple-50' },
    ];

    return (
        <div className="w-full space-y-6">
            {/* Welcome Section - Beautiful Gradient */}
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="relative overflow-hidden rounded-2xl p-6 md:p-8 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"
            >
                <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-white/10 rounded-full blur-2xl"></div>
                
                <div className="relative flex flex-wrap items-start justify-between gap-4">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold text-white mb-2">
                            👋 Welcome back, {user?.fullName?.split(' ')[0] || user?.username}!
                        </h1>
                        <p className="text-white/80 text-base md:text-lg">
                            Let's finish your tasks today! 🏆
                        </p>
                        <div className="flex flex-wrap gap-2 mt-3">
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs md:text-sm text-white flex items-center gap-1">
                                <Flame size={14} />
                                {streak} day streak
                            </span>
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs md:text-sm text-white flex items-center gap-1">
                                <Award size={14} />
                                {completionRate}% complete
                            </span>
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs md:text-sm text-white flex items-center gap-1">
                                <Target size={14} />
                                {daysRemaining} days left
                            </span>
                        </div>
                    </div>
                    <div className="bg-white/20 px-4 py-2 rounded-xl text-center backdrop-blur-sm">
                        <div className="text-2xl md:text-3xl font-bold text-white">{completionRate}%</div>
                        <div className="text-xs text-white/70">Progress</div>
                    </div>
                </div>
            </motion.div>

            {/* Quick Stats - 4 cards */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {quickStats.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <motion.div
                            key={index}
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ delay: index * 0.1 }}
                            className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 hover:shadow-md transition"
                        >
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-xs text-gray-400">{stat.label}</p>
                                    <p className="text-xl font-bold text-gray-800 mt-1">{stat.value}</p>
                                </div>
                                <div className={`${stat.bg} p-2.5 rounded-xl`}>
                                    <Icon className={stat.color} size={20} />
                                </div>
                            </div>
                        </motion.div>
                    );
                })}
            </div>

            {/* Weekly Progress and Today's Tasks */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <motion.div 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100"
                >
                    <h3 className="text-lg font-semibold text-gray-800 mb-4">📊 This Week's Progress</h3>
                    <div className="space-y-4">
                        <div>
                            <div className="flex justify-between text-sm mb-1">
                                <span className="text-gray-500">Week Progress</span>
                                <span className="font-bold text-gray-800">{weekProgress}%</span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-2.5">
                                <div 
                                    className="bg-gradient-to-r from-indigo-500 to-purple-500 h-2.5 rounded-full transition-all"
                                    style={{ width: `${weekProgress}%` }}
                                />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="bg-gray-50 rounded-xl p-4 text-center">
                                <p className="text-2xl font-bold text-indigo-500">{weekCompleted}</p>
                                <p className="text-xs text-gray-500">Tasks Done</p>
                            </div>
                            <div className="bg-gray-50 rounded-xl p-4 text-center">
                                <p className="text-2xl font-bold text-purple-500">{weekTasks.length}</p>
                                <p className="text-xs text-gray-500">Total Tasks</p>
                            </div>
                        </div>
                        <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-xl p-4 text-center">
                            <p className="text-sm text-gray-500">Days Remaining</p>
                            <p className="text-2xl font-bold text-orange-500">{daysRemaining} days</p>
                            <p className="text-xs text-gray-400">Until November 30, 2026</p>
                        </div>
                    </div>
                </motion.div>

                <motion.div 
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100"
                >
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="text-lg font-semibold text-gray-800">✅ Today's Tasks</h3>
                        <span className="text-xs text-gray-400">{todayCompleted}/{todayTasks.length} done</span>
                    </div>
                    {todayTasks.length > 0 ? (
                        <div className="space-y-2">
                            {todayTasks.slice(0, 5).map((task, idx) => {
                                const labels = ['Java', 'LeetCode', 'DSA', 'SQL', 'Project', 'GitHub'];
                                const statuses = [task.javaCompleted, task.leetcodeCompleted, task.dsaCompleted, task.sqlCompleted, task.projectCompleted, task.githubCompleted];
                                return (
                                    <div key={idx} className="flex items-center gap-3 p-2 rounded-xl bg-gray-50">
                                        {statuses[idx] ? 
                                            <CheckCircle size={18} className="text-green-500 flex-shrink-0" /> : 
                                            <Circle size={18} className="text-gray-300 flex-shrink-0" />
                                        }
                                        <span className={`text-sm ${statuses[idx] ? 'text-gray-400 line-through' : 'text-gray-700'}`}>
                                            {labels[idx]}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="text-center py-8 text-gray-400">
                            <p className="text-sm">No tasks for today</p>
                            <p className="text-xs">Click on a day in the tracker to start</p>
                        </div>
                    )}
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="mt-4 text-indigo-500 text-sm font-medium hover:text-indigo-700 transition flex items-center gap-1"
                    >
                        View all tasks <ArrowRight size={16} />
                    </button>
                </motion.div>
            </div>

            {/* Quick Actions - 3 Beautiful Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.1 }}
                    className="bg-gradient-to-r from-indigo-500 to-blue-500 rounded-2xl p-6 text-white hover:shadow-xl transition"
                >
                    <div className="flex items-start justify-between">
                        <div>
                            <h4 className="text-lg font-semibold mb-1">📝 Log Today</h4>
                            <p className="text-indigo-100 text-sm mb-4">Track your daily progress</p>
                            <button 
                                onClick={() => window.location.href = '/tracker'}
                                className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-xl text-sm font-medium transition"
                            >
                                Go to Tracker →
                            </button>
                        </div>
                        <Sparkles size={28} className="text-white/50" />
                    </div>
                </motion.div>

                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.2 }}
                    className="bg-gradient-to-r from-purple-500 to-pink-500 rounded-2xl p-6 text-white hover:shadow-xl transition"
                >
                    <div className="flex items-start justify-between">
                        <div>
                            <h4 className="text-lg font-semibold mb-1">📚 Roadmap</h4>
                            <p className="text-purple-100 text-sm mb-4">View your 4-month plan</p>
                            <button 
                                onClick={() => window.location.href = '/weekly-focus'}
                                className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-xl text-sm font-medium transition"
                            >
                                View Roadmap →
                            </button>
                        </div>
                        <BookOpen size={28} className="text-white/50" />
                    </div>
                </motion.div>

                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="bg-gradient-to-r from-green-500 to-teal-500 rounded-2xl p-6 text-white hover:shadow-xl transition"
                >
                    <div className="flex items-start justify-between">
                        <div>
                            <h4 className="text-lg font-semibold mb-1">📊 Analytics</h4>
                            <p className="text-green-100 text-sm mb-4">Detailed progress stats</p>
                            <button 
                                onClick={() => window.location.href = '/progress'}
                                className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-xl text-sm font-medium transition"
                            >
                                View Analytics →
                            </button>
                        </div>
                        <Database size={28} className="text-white/50" />
                    </div>
                </motion.div>
            </div>
        </div>
    );
};

export default Dashboard;
